.ds .ds-button:not(:disabled):is(:active,[data-state="pressed"]) { box-shadow:var(--p-pressed); }
.ds .ds-button:not([data-variant="primary"]):not(:disabled):is(:active,[data-state="pressed"]) { background:var(--p-bg); box-shadow:var(--p-inset); }
.ds .ds-button[data-state="focus"] { outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset); }
.ds .ds-button:disabled { opacity:var(--p-opacity-full); box-shadow:none; background:var(--p-disabled); border-color:var(--p-line); color:var(--p-muted); }
.ds .ds-button[aria-busy="true"] { background:var(--p-accent); color:var(--p-on-accent); border-color:var(--p-accent); }
.ds .ds-spinner { width:var(--p-size-md); height:var(--p-size-md); flex-shrink:0; border:var(--p-border-width-strong) solid currentColor; border-right-color:transparent; border-radius:var(--p-radius-circle); animation:ds-spin var(--p-duration-spin) var(--p-ease-linear) infinite; }
@keyframes ds-spin { to { transform:rotate(360deg); } }
@media(prefers-reduced-motion:reduce) { .ds .ds-spinner { border-style:var(--p-stroke-dotted); } }
/* looks: 채움(primary) · 윤곽(outline) · 글자(ghost) are the data-variant colour roles above */
.ds .ds-button-count { display:inline-grid; place-items:center; min-width:var(--p-size-lg); height:var(--p-size-lg); padding:0 var(--p-space-xs); border-radius:var(--p-radius-full); background:var(--p-accent); color:var(--p-on-accent); font-size:var(--p-text-sm); font-weight:var(--p-weight-bold); line-height:var(--p-leading-none); }
.ds .ds-button[data-variant="primary"] .ds-button-count { background:var(--p-on-accent); color:var(--p-accent); }

.ds .ds-nav { max-inline-size:100%; min-inline-size:0; container-type:inline-size; container-name:pattove-nav; }
.ds .ds-nav :is(ul,ol) { padding:0; margin:0; list-style:none; }
.ds .ds-nav :is(a,summary) { color:var(--p-ink); text-underline-offset:var(--p-space-2xs); }
.ds .ds-nav h2 { font-size:var(--p-text-title); }
.ds .ds-nav-links { display:flex; flex-wrap:wrap; gap:var(--p-space-xs); }
.ds .ds-nav-links > li { min-inline-size:0; }
.ds .ds-nav-links a { min-block-size:var(--p-control-size-sm); padding:var(--p-space-xs) var(--p-space-sm); display:flex; align-items:center; gap:var(--p-space-xs); border-radius:var(--p-radius); }
.ds .ds-nav [aria-current="page"],.ds .ds-nav [aria-current="step"] { font-weight:var(--p-weight-bold); background:var(--p-soft); }
.ds .ds-nav-brand { font-size:var(--p-text-title); font-weight:var(--p-weight-bold); text-decoration:none; }
.ds :is(.ds-site-header,.ds-service-navigation) { display:flex; flex-wrap:wrap; align-items:center; justify-content:space-between; gap:var(--p-space-md); padding-block:var(--p-space-md); border-block-end:var(--p-border-width) solid var(--p-line); }
.ds .ds-nav-disclosure { min-inline-size:0; }
.ds .ds-nav-disclosure > summary { cursor:pointer; min-block-size:var(--p-control-size-sm); padding:var(--p-space-sm); border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); }
.ds .ds-nav-disclosure[open] > summary { background:var(--p-soft); }
.ds .ds-nav-disclosure > :not(summary) { margin-block-start:var(--p-space-sm); }
.ds .ds-nav-disclosure .ds-nav-links { display:grid; }
.ds .ds-mega-menu { display:flex; flex-wrap:wrap; gap:var(--p-space-md); }
.ds .ds-mega-menu > details { flex:1 1 var(--p-container-2xs); }
.ds .ds-nav-mega-body { padding:var(--p-space-md); border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); }
.ds .ds-site-footer { display:grid; gap:var(--p-space-lg); padding:var(--p-space-lg); border-block-start:var(--p-border-width) solid var(--p-line); }
.ds .ds-nav-tree { display:grid; gap:var(--p-space-xs); }
.ds .ds-nav-tree li > a { display:inline-flex; min-block-size:var(--p-control-size-sm); align-items:center; padding-inline:var(--p-space-sm); }
.ds .ds-nav-tree ul,.ds .ds-nav-tree details { margin-inline-start:var(--p-space-lg); }
.ds .ds-site-map h2 { margin-block-end:var(--p-space-md); }
.ds .ds-app-switcher .ds-nav-links { grid-template-columns:repeat(2,minmax(0,1fr)); }
.ds .ds-app-switcher a,.ds .ds-navigation-rail a { flex-direction:column; justify-content:center; text-align:center; }
.ds .ds-nav-symbol { display:grid; place-items:center; inline-size:var(--p-control-size-sm); block-size:var(--p-control-size-sm); border-radius:var(--p-radius); background:var(--p-soft); }
.ds .ds-navigation-rail { max-inline-size:calc(var(--p-space-unit) * 24); }
.ds .ds-navigation-rail .ds-nav-links { display:grid; }
.ds .ds-page-header { display:grid; gap:var(--p-space-md); padding-block:var(--p-space-lg); }
.ds .ds-page-header > div { display:flex; flex-wrap:wrap; align-items:center; justify-content:space-between; gap:var(--p-space-md); }
.ds .ds-page-header :is(h1,h2) { font-size:var(--p-text-heading); }
.ds .ds-nav-utility { display:flex; justify-content:end; padding-block:var(--p-space-xs); border-block-end:var(--p-border-width) solid var(--p-line); }
.ds .ds-nav-utility a { font-size:var(--p-text-sm); }
.ds .ds-tag-cloud ul { display:flex; flex-wrap:wrap; align-items:baseline; gap:var(--p-space-lg); }
.ds .ds-tag-cloud li { font-size:var(--p-text-body); }
.ds .ds-tag-cloud li[data-rank="2"] { font-size:var(--p-text-title); }
.ds .ds-tag-cloud li[data-rank="3"] { font-size:var(--p-text-heading); }
.ds .ds-tag-cloud a { display:inline-flex; align-items:baseline; gap:var(--p-space-xs); min-block-size:var(--p-control-size-sm); }
.ds .ds-tag-cloud a span { font-size:var(--p-text-sm); }
.ds :is(.ds-table-of-contents,.ds-in-page-navigation) { display:flex; flex-wrap:wrap; align-items:start; gap:var(--p-space-xl); }
.ds :is(.ds-table-of-contents,.ds-in-page-navigation) > nav { flex:1 1 var(--p-container-2xs); }
.ds .ds-nav-sections { flex:3 1 var(--p-container-sm); min-inline-size:0; }
.ds .ds-nav-sections > section { padding-block:var(--p-space-lg); display:grid; gap:var(--p-space-sm); }
.ds .ds-nav-jump { display:inline-flex; align-items:center; min-block-size:var(--p-control-size-sm); padding:var(--p-space-xs); }
.ds .ds-nav [tabindex="-1"] { scroll-margin-block-start:var(--p-space-xl); }
.ds :is(.ds-skip-link,.ds-back-to-top,.ds-footer-anchor) { display:grid; gap:var(--p-space-lg); }
.ds .ds-alphabet-index > nav ul { display:flex; flex-wrap:wrap; gap:var(--p-space-sm); }
.ds .ds-alphabet-index > section { margin-block-start:var(--p-space-xl); }
.ds .ds-navigation-progress progress { display:block; inline-size:100%; block-size:var(--p-size-xs); accent-color:var(--p-accent); }
.ds :is(.ds-step-list,.ds-journey-navigation) > ol { display:grid; gap:var(--p-space-md); }
.ds .ds-step-list li { display:flex; gap:var(--p-space-md); align-items:center; padding:var(--p-space-sm); border-radius:var(--p-radius); }
.ds .ds-nav-step-number { inline-size:var(--p-control-size-sm); block-size:var(--p-control-size-sm); display:grid; place-items:center; border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); }
.ds .ds-nav-step-state { display:block; font-size:var(--p-text-sm); color:var(--p-muted); }
.ds .ds-journey-navigation p { padding:var(--p-space-sm); }
.ds .ds-journey-navigation a { display:inline-flex; min-block-size:var(--p-control-size-sm); align-items:center; padding-inline:var(--p-space-sm); }
.ds .ds-nav-button { min-block-size:var(--p-control-size-sm); min-inline-size:var(--p-control-size-sm); padding:var(--p-space-xs) var(--p-space-sm); border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); background:var(--p-surface); }
.ds .ds-select-navigation { display:flex; flex-wrap:wrap; gap:var(--p-space-sm); align-items:center; }
.ds .ds-select-navigation select { max-inline-size:100%; min-block-size:var(--p-control-size-sm); padding-inline:var(--p-space-sm); border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); background:var(--p-surface); }
.ds .ds-nav-back-path { display:none; }
.ds .ds-responsive-pagination { display:flex; flex-wrap:wrap; gap:var(--p-space-xs); align-items:center; }
.ds .ds-nav-pages { display:flex; flex-wrap:wrap; align-items:center; gap:var(--p-space-xs); }
.ds .ds-fullscreen-navigation .ds-dialog { inset:0; inline-size:100%; max-inline-size:100%; block-size:100dvh; max-block-size:100dvh; margin:0; border-radius:0; }
.ds .ds-overflow-navigation { overflow-x:auto; }
.ds .ds-overflow-navigation .ds-nav-links { flex-wrap:nowrap; }
.ds .ds-overflow-navigation li { flex-shrink:0; }
@container pattove-nav (max-width:760px) {
 .ds .ds-responsive-pagination:not(.ds-conditional-pagination) .ds-nav-pages { display:none; }
 .ds .ds-compact-breadcrumb li:not(:nth-last-child(2)):not(:only-child) { display:none; }
 .ds .ds-breadcrumb-back .ds-nav-full-path { display:none; }
 .ds .ds-breadcrumb-back .ds-nav-back-path { display:inline-flex; min-block-size:var(--p-control-size-sm); align-items:center; }
}

(function mountParts(root) {
  window.Pattove?.admin?.mount(root);
  root.querySelectorAll('[data-await-script]').forEach(fieldset=>{fieldset.disabled=false;fieldset.removeAttribute('data-await-script');});
  root.querySelectorAll('[data-indeterminate]').forEach(input => {
    if (!input.__pattoveInitialized) { input.indeterminate = true; input.__pattoveInitialized = true; }
  });
  const syncStepper=input=>{
    const box=input.closest('.ds-stepper');if(!box)return;
    for(const button of box.querySelectorAll('[data-step]'))button.disabled=input.disabled||(input.value!==''&&(Number(button.dataset.step)<0?input.min!==''&&input.valueAsNumber<=Number(input.min):input.max!==''&&input.valueAsNumber>=Number(input.max)));
  };
  root.querySelectorAll('.ds-stepper input').forEach(syncStepper);
  const placeLayouts=()=>root.querySelectorAll('[data-layout-append]').forEach(node=>{
    const movable=node.querySelector('[data-layout-movable]');
    const target=node.querySelector(innerWidth<=760?'[data-layout-narrow-slot]':'[data-layout-wide-slot]');
    if(movable&&target&&movable.parentElement!==target){const focus=movable.contains(document.activeElement)?document.activeElement:null;target.append(movable);focus?.focus({preventScroll:true});}
  });
  placeLayouts();
  if (root.__pattovePartsMounted) return;
  root.__pattovePartsMounted = true;
  const emit = (node, name, detail) => node.dispatchEvent(new CustomEvent('pattove:' + name, {bubbles:true, detail}));
  window.addEventListener('resize',placeLayouts);
  root.addEventListener('keydown',e=>{
    const disclosure=e.target.closest('[data-nav-disclosure]');
    if(e.key==='Escape'&&disclosure?.open){e.preventDefault();e.stopPropagation();disclosure.open=false;disclosure.querySelector(':scope > summary')?.focus();}
  });
  root.addEventListener('focusout',e=>{
    const disclosure=e.target.closest('[data-nav-disclosure]');
    if(disclosure&&e.relatedTarget&&!disclosure.contains(e.relatedTarget))disclosure.open=false;
  });
  root.addEventListener('submit',e=>{
    const form=e.target.closest('[data-nav-select]');if(!form)return;e.preventDefault();const selected=form.querySelector('select').selectedOptions[0];if(!selected)return;
    const href=selected.value,event=new CustomEvent('pattove:navigate',{bubbles:true,cancelable:true,detail:{href,label:selected.textContent}});
    if(form.dispatchEvent(event))location.assign(href);
  });
  root.addEventListener('click',e=>{
    const jump=e.target.closest('[data-nav-target]');if(jump){const target=document.getElementById(jump.dataset.navTarget);if(target){if(!target.hasAttribute('tabindex'))target.tabIndex=-1;target.focus({preventScroll:true});}}
    const link=e.target.closest('[data-nav-dialog] a');if(link)link.closest('dialog')?.close();
    const button=e.target.closest('[data-nav-step],[data-nav-page]');if(!button)return;
    const nav=button.closest('[data-nav-pagination]'),total=Number(nav.dataset.total),page=Math.max(1,Math.min(total,button.hasAttribute('data-nav-page')?Number(button.dataset.navPage):Number(nav.dataset.page)+Number(button.dataset.navStep)));
    const wasNumber=button.hasAttribute('data-nav-page');nav.dataset.page=String(page);nav.querySelector('output').textContent=page+' / '+total;
